INSERT INTO LIVROS_NOMES (NOME, ESTADO, SUGESTAO_TITULO, SUGESTAO_AUTOR, CERTEZA, MOTIVO, CONFERIDO, TIPO_SUG, SUBTIPO, CRIADO_EM) VALUES ('{{nome}}', 'PENDENTE', NULLIF(LEFT('{{titulo}}', 300), ''), NULLIF(LEFT('{{autor}}', 200), ''), {{certeza}}, LEFT('{{motivo}}', 300), 'IMPORTADO', NULLIF('{{tipo}}', ''), NULLIF('{{subtipo}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) ON DUPLICATE KEY UPDATE SUGESTAO_TITULO = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_TITULO), SUGESTAO_TITULO), SUGESTAO_AUTOR = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_AUTOR), SUGESTAO_AUTOR), CERTEZA = IF(ESTADO = 'PENDENTE', VALUES(CERTEZA), CERTEZA), MOTIVO = IF(ESTADO = 'PENDENTE', VALUES(MOTIVO), MOTIVO), CONFERIDO = IF(ESTADO = 'PENDENTE', 'IMPORTADO', CONFERIDO), TIPO_SUG = IF(ESTADO = 'PENDENTE', VALUES(TIPO_SUG), TIPO_SUG), SUBTIPO = IF(ESTADO = 'PENDENTE', VALUES(SUBTIPO), SUBTIPO)